build.VisitAllChildren<Message>(msg => {
    if (msg.Text != null && (msg.Text.Contains("not build") || msg.Text.Contains("failed") || msg.Text.Contains("skipped") || msg.Text.Contains("dependency")))
        if (msg.Text.Contains("Api") || msg.Text.Contains("Core") || msg.Text.Contains("Services") || msg.Text.Contains("project"))
            Console.WriteLine($"  {msg.Text}");
});

Console.WriteLine("\n=== CSC command for Services ===");
